using System;
using System.IO;
using System.Linq;
using Godot;

namespace CCCPRacing.Race;

/// <summary>
/// Deck freeze diagnostics (2026-11-22, the owner's consultation with Codex): the audio thread spins in AudioStreamPlaybackResampled::mix (a generator's playback) while the main thread waits for the audio lock.
/// This logs which driver is really in use and the lifecycle of every generator player (path, instance id, thread, Play/Stop) into stall.log, and has a switch that keeps the generators from playing at all:
/// the file "diag-nogen" in the user data directory (the rest of the sound, the graphics and the track change are as they are). The audio probe (tools/diag/audioprobe.c) reads the spinning thread's registers
/// and the resampler's fields when the watchdog fires. Nothing here changes the sound when the switch file is absent.
/// </summary>
public partial class AudioDiag : Node
{
    public static bool NoGen { get; private set; }
    public static int Mixes => _lifecycle;
    static int _lifecycle;
    double _sweep;

    public static void Install(Node owner)
    {
        try
        {
            string dir = OS.GetUserDataDir();
            NoGen = File.Exists(Path.Combine(dir, "diag-nogen"));
            var args = string.Join(' ', OS.GetCmdlineArgs());
            StallWatch.Note($"AUDIO DIAG: driver setting '{ProjectSettings.GetSetting("audio/driver/driver", "")}', args '{args}', output device '{AudioServer.GetOutputDevice()}', mix rate {AudioServer.GetMixRate()}, output latency {AudioServer.GetOutputLatency():F3}, generators muted by diag-nogen: {NoGen}");
            var d = new AudioDiag { Name = "AudioDiag", ProcessMode = ProcessModeEnum.Always };
            owner.AddChild(d);
            var tree = owner.GetTree();
            tree.NodeAdded += n => d.Added(n);
            tree.NodeRemoved += n => d.Removed(n);
        }
        catch (Exception ex) { StallWatch.Note("AUDIO DIAG failed: " + ex.GetType().Name + " " + ex.Message); }
    }

    static bool IsGen(Node n) => n is AudioStreamPlayer { Stream: AudioStreamGenerator } or AudioStreamPlayer3D { Stream: AudioStreamGenerator };

    static string Describe(Node n)
    {
        bool playing = n is AudioStreamPlayer p ? p.Playing : n is AudioStreamPlayer3D p3 && p3.Playing;
        return $"{n.GetType().Name} {n.Name} id {n.GetInstanceId()} playing {playing} path {(n.IsInsideTree() ? n.GetPath().ToString() : "(outside tree)")}";
    }

    void Added(Node n)
    {
        if (n is not (AudioStreamPlayer or AudioStreamPlayer3D)) return;
        CallDeferred(nameof(AfterAdded), n);
    }

    void AfterAdded(Node n)
    {
        if (!IsInstanceValid(n) || !IsGen(n)) return;
        _lifecycle++;
        if (NoGen) Silence(n);
        StallWatch.Note("AUDIO GEN added: " + Describe(n) + (NoGen ? " (muted by diag-nogen)" : ""));
    }

    void Removed(Node n)
    {
        if (!IsInstanceValid(n) || !IsGen(n)) return;
        _lifecycle++;
        StallWatch.Note("AUDIO GEN removed: " + Describe(n));
    }

    static void Silence(Node n)
    {
        if (n is AudioStreamPlayer p && p.Playing) p.Stop();
        else if (n is AudioStreamPlayer3D p3 && p3.Playing) p3.Stop();
    }

    public override void _Process(double delta)
    {
        if (!NoGen) return;
        _sweep += delta;
        if (_sweep < 0.2) return;
        _sweep = 0;
        foreach (var n in GetTree().Root.FindChildren("*", "", true, false))
            if (IsGen(n)) Silence(n);
    }
}

/// <summary>The audio probe (tools/diag/audioprobe.c, no libc, 9 KB): registers of one thread and the memory around r13/rbx/rbp/r12.</summary>
public static class AudioProbe
{
    const string Base64 = "";

    public static string Run(int tid, string dir)
    {
        if (!OperatingSystem.IsLinux() || System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture != System.Runtime.InteropServices.Architecture.X64 || tid == 0) return "";
        try
        {
            string exe = Path.Combine(dir, "audioprobe");
            if (!File.Exists(exe)) { File.WriteAllBytes(exe, Convert.FromBase64String(Base64)); File.SetUnixFileMode(exe, (UnixFileMode)0b111_101_101); }
            var psi = new System.Diagnostics.ProcessStartInfo(exe, $"{tid} /proc/{System.Environment.ProcessId}/mem") { RedirectStandardOutput = true, UseShellExecute = false };
            using var proc = System.Diagnostics.Process.Start(psi);
            string text = proc.StandardOutput.ReadToEnd();
            if (!proc.WaitForExit(3000)) { try { proc.Kill(); } catch { } }
            return text.Replace('\n', '|').TrimEnd('|');
        }
        catch (Exception ex) { return "(audio probe failed: " + ex.GetType().Name + ")"; }
    }
}
